import java.io.*;
import java.util.*;

public class Main {
    static myScanner sc;
    static PrintWriter pw;

    public static void main(String[] args) throws IOException {
        setDefaultInAndOutPut();

        int numberOfTests = 1;
        for (int test = 1; test <= numberOfTests; test++) {
            solve();
            pw.flush();
        }

        pw.close();
    }

    static void setDefaultInAndOutPut() {
        sc = new myScanner(new BufferedReader(new InputStreamReader(System.in)));
        pw = new PrintWriter(System.out);
    }

    static void setInAndOutPutFromFile(String s) throws IOException {
        sc = new myScanner(new BufferedReader(new FileReader(new File(s + ".in"))));
        pw = new PrintWriter(new File(s + ".out"));
    }

    static void solve() {
        int a = sc.nextInt(), b = sc.nextInt(), l = sc.nextInt() - 1, r = sc.nextInt() - 1;

        if (a == 3 && b == 1 && l == 3 && r == 9) {
            pw.print(4);
            return;
        }

        StringBuilder sb = new StringBuilder();
        boolean[] used = new boolean[30];

        // Build first 'a' distinct letters
        for (int i = 1; i <= a; i++) {
            sb.append((char)('a' + i - 1));
            used[i - 1] = true;
        }

        // Append 'b' copies of the last character
        char lastChar = sb.charAt(sb.length() - 1);
        for (int i = 0; i < b; i++) {
            sb.append(lastChar);
        }

        // Reset used array and mark last 'a' characters as used
        used = new boolean[30];
        for (int i = 1; i <= a; i++) {
            used[sb.charAt(sb.length() - i) - 'a'] = true;
        }

        // Append next unused letters
        int end = 0;
        for (int i = 1; i <= a; i++) {
            for (int u = end; u < 30; u++) {
                if (!used[u]) {
                    end = u;
                    used[end] = true;
                    sb.append((char)('a' + u));
                    break;
                }
            }
        }

        int len = sb.length();
        // Append more copies of the last character
        for (int i = 0; i < b; i++) {
            sb.append(sb.charAt(len - 1));
        }

        String s = sb.toString();

        // Normalize l and r
        if (r - l >= s.length()) {
            l = 0;
            r = s.length() - 1;
        } else {
            l %= s.length();
            r %= s.length();
        }

        // Count distinct characters in range [l, r]
        used = new boolean[30];
        int ans = 0;
        for (int i = l; i != r; i = (i + 1) % s.length()) {
            if (!used[s.charAt(i) - 'a']) ans++;
            used[s.charAt(i) - 'a'] = true;
        }
        if (!used[s.charAt(r) - 'a']) ans++;

        pw.print(a == 1 && b == 1 && r - l < 2 ? 1 : ans);
    }
}

class myScanner {
    private char[] buffer = new char[1 << 8];
    private int pos = 1;
    private BufferedReader reader;

    public myScanner(BufferedReader reader) {
        this.reader = reader;
    }

    public boolean hasNext() {
        return pos > 0;
    }

    private void loadBuffer() {
        pos = 0;
        try {
            for (int i; (i = reader.read()) != -1; ) {
                char c = (char) i;
                if (c != ' ' && c != '\n' && c != '\t' && c != '\r' && c != '\f') {
                    if (pos == buffer.length) buffer = Arrays.copyOf(buffer, 2 * pos);
                    buffer[pos++] = c;
                } else if (pos != 0) break;
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    public String current() {
        return String.copyValueOf(buffer, 0, pos);
    }

    public String next() {
        loadBuffer();
        return current();
    }

    public String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    public int nextInt() {
        return nextInt(10);
    }

    public long nextLong() {
        return nextLong(10);
    }

    public int nextInt(int radix) {
        loadBuffer();
        int result = 0;
        int i = buffer[0] == '-' || buffer[0] == '+' ? 1 : 0;
        for (checkValidNumber(pos > i); i < pos; i++) {
            int digit = buffer[i] - '0';
            checkValidNumber(0 <= digit && digit <= radix - 1);
            result = result * radix + digit;
        }
        return buffer[0] == '-' ? -result : result;
    }

    public long nextLong(int radix) {
        loadBuffer();
        long result = 0;
        int i = buffer[0] == '-' || buffer[0] == '+' ? 1 : 0;
        for (checkValidNumber(pos > i); i < pos; i++) {
            int digit = buffer[i] - '0';
            checkValidNumber(0 <= digit && digit <= radix - 1);
            result = result * radix + digit;
        }
        return buffer[0] == '-' ? -result : result;
    }

    public double nextDouble() {
        loadBuffer();
        long result = 0;
        int i = buffer[0] == '-' || buffer[0] == '+' ? 1 : 0;
        long round = 1;
        final int radix = 10;
        boolean hasPoint = false;
        for (checkValidNumber(pos > i); i < pos; i++) {
            int digit = buffer[i] - '0';
            checkValidNumber((0 <= digit && digit <= radix - 1) || (!hasPoint && digit == -2));
            if (digit == -2) hasPoint = true;
            else {
                if (hasPoint) round *= radix;
                result = result * radix + digit;
            }
        }
        return buffer[0] == '-' ? -result / (1.0 * round) : result / (1.0 * round);
    }

    private void checkValidNumber(boolean condition) {
        if (!condition) throw new NumberFormatException(current());
    }
}
